process.on("SIGINT", () => process.exit(SIGINT_EXIT));
try {
  process.exitCode = await main(process.argv.slice(2));
} catch (error) {
  console.error(`cc-smart-dev-kit portal: ${error instanceof Error ? error.message : String(error)}`);
  process.exitCode = 1;
}
